import sys

def solve():
    tokens = sys.stdin.read().split()
    if not tokens:
        return

    it = 0
    while it < len(tokens):
        n = int(tokens[it])
        it += 1

        d_count = {}
        e_count = {}

        for _ in range(n):
            m = int(tokens[it])
            l = tokens[it + 1]
            it += 2

            if l == 'D':
                d_count[m] = d_count.get(m, 0) + 1
            else:
                e_count[m] = e_count.get(m, 0) + 1

        total_pares = 0
        all_sizes = set(d_count.keys()) | set(e_count.keys())
        for m in all_sizes:
            total_pares += min(d_count.get(m, 0), e_count.get(m, 0))

        print(total_pares)

if __name__ == '__main__':
    solve()
